        check("toBinary(0)", "0", BinaryRecursive.toBinary(0));
        check("toBinary(1)", "1", BinaryRecursive.toBinary(1));
        check("toBinary(2)", "10", BinaryRecursive.toBinary(2));
        check("toBinary(6)", "110", BinaryRecursive.toBinary(6));
        check("toBinary(255)", "11111111", BinaryRecursive.toBinary(255));
        check("toBinary(1024)", "10000000000", BinaryRecursive.toBinary(1024));
        check("matches library for 987654", Integer.toBinaryString(987654), BinaryRecursive.toBinary(987654));
